// Package file manages files maisys writes: copied or rendered from the
// config repo by the files module, or generated by other modules (rc and
// environment files, wsl.conf). It keeps the sha256 of what it wrote, so
// the plan can tell a file maisys wrote from one changed outside maisys,
// and backs files up before it overwrites changes it didn't make.
package file

import (
	"bytes"
	"context"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"runtime"
	"slices"
	"time"

	"github.com/plombardi89/maisys2/internal/resource"
	"github.com/plombardi89/maisys2/internal/state"
	"github.com/plombardi89/maisys2/internal/system"
)

// Kind is the kind of resource a File is.
const Kind = "file"

// The keys of a file record's Details.
const (
	// DetailHash is the sha256 of what maisys wrote, in hex.
	DetailHash = "sha256"
	// DetailRoot is "true" for a file written as root.
	DetailRoot = "root"
)

// privateDirs are the folders in the home folder that maisys creates
// readable only by you, if it creates them.
var privateDirs = []string{".ssh", ".gnupg"}

// File is a file maisys writes. Its check reports:
//
//   - "+ path" if the file is missing;
//   - "~ path" if maisys wrote it and it should change;
//   - "! path changed outside maisys (will back up and overwrite)" if it's
//     been changed since maisys wrote it;
//   - "! path exists (will back up and take over)" the first time maisys
//     manages a file that's there already with other contents. Its record
//     says maisys took it over, so it's left in place once it's taken out
//     of the config.
//
// A file that's there already with the right contents is taken over too,
// without a change in the plan: the check only says what its record
// should be (see resource.Change.Record).
//
// Applying backs a file up to <path>.maisys-bak.<timestamp> before it
// overwrites changes maisys didn't make. Files are written to a temporary
// file in the same folder that's then renamed over the file, so they're
// never left half written; missing folders are created.
type File struct {
	// Path is where the file goes: "~/..." in your home folder, or an
	// absolute path for a file outside it, which needs Root.
	Path string
	// Content returns what the file holds.
	Content Content
	// Mode sets the file's permissions. Zero means 0644 for a new file and
	// keeping an existing file's, with the executable bits set from
	// Executable either way. Windows has no permission bits, so it's
	// ignored there.
	Mode fs.FileMode
	// Executable makes the file executable when Mode is zero.
	Executable bool
	// CRLF converts the content's line endings to CRLF.
	CRLF bool
	// Root writes the file as root, with system.InstallFile, in a folder
	// that exists. Only Linux has it.
	Root bool
	// Key, if set, is the resource's ID, for resources that manage a file
	// as part of something else, such as a systemd unit. Empty means
	// "file:" followed by the path as Display shows it.
	Key string
}

var _ resource.Resource = (*File)(nil)

// ID returns the file's ID, such as "file:~/.gitconfig".
func (f *File) ID() string {
	if f.Key != "" {
		return f.Key
	}
	return Kind + ":" + Display(f.Path)
}

// Kind returns "file".
func (f *File) Kind() string { return Kind }

// Targets returns the file's path, as Display shows it.
func (f *File) Targets() []string { return []string{Display(f.Path)} }

// Privileged reports whether the file is written as root.
func (f *File) Privileged() bool { return f.Root }

// Check compares the file on disk with what it should hold. If it already
// holds that, but the state file's record of it is missing or out of date,
// the change has the record applying would leave.
func (f *File) Check(_ context.Context, rt *resource.Runtime) (resource.Change, error) {
	in, err := f.inspect(rt)
	if err != nil {
		return resource.Change{}, err
	}
	c := in.change()
	if rec := f.record(in); c.Action == resource.NoChange && !in.current(rec) {
		c.Record = &rec
	}
	return c, nil
}

// Apply writes the file, backing up what's there first if maisys didn't
// write it, and returns its record: the hash of what it wrote, and whether
// maisys took it over.
func (f *File) Apply(ctx context.Context, rt *resource.Runtime) (state.Record, error) {
	in, err := f.inspect(rt)
	if err != nil {
		return state.Record{}, err
	}
	rec := f.record(in)
	if in.change().Action == resource.NoChange {
		return rec, nil
	}

	if in.needsBackup() {
		if err := f.backup(ctx, rt, in); err != nil {
			return state.Record{}, err
		}
	}
	if f.Root {
		err = system.InstallFile(ctx, rt.Runner, in.want, in.path, in.perm)
	} else {
		err = write(rt.Paths.Home, in.path, in.want, in.perm)
	}
	if err != nil {
		return state.Record{}, err
	}
	return rec, nil
}

// inspection is what a file's check found.
type inspection struct {
	path    string // the absolute path
	display string // the path as the plan shows it
	want    []byte // what the file should hold
	perm    fs.FileMode
	exists  bool
	link    bool   // whether the path is a symlink
	regular bool   // whether the path is a file, or a link to one
	cur     []byte // what the file holds, if it's regular
	curPerm fs.FileMode
	prev    state.Record // the record of the last apply, if any
}

func (f *File) inspect(rt *resource.Runtime) (*inspection, error) {
	if f.Content == nil {
		return nil, fmt.Errorf("%s has no content", f.Path)
	}
	path, err := Expand(rt.Paths.Home, f.Path)
	if err != nil {
		return nil, err
	}
	in := &inspection{path: path, display: Display(f.Path)}
	if in.want, err = f.Content(rt); err != nil {
		return nil, err
	}
	if f.CRLF {
		in.want = toCRLF(in.want)
	}
	if rt.Previous != nil {
		in.prev, _ = rt.Previous(f.ID())
	}

	info, err := os.Lstat(path)
	switch {
	case errors.Is(err, fs.ErrNotExist):
		in.perm = f.wantPerm(0, false)
		return in, nil
	case err != nil:
		return nil, fmt.Errorf("reading %s: %w", in.display, err)
	}
	in.exists = true
	in.link = info.Mode()&fs.ModeSymlink != 0
	if in.link {
		// What a link points to is compared, if it points to anything.
		if target, err := os.Stat(path); err == nil {
			info = target
		}
	}
	switch {
	case info.IsDir():
		return nil, fmt.Errorf("%s is a folder, not a file", in.display)
	case info.Mode().IsRegular():
		in.regular, in.curPerm = true, info.Mode().Perm()
		if in.cur, err = os.ReadFile(path); err != nil {
			return nil, fmt.Errorf("reading %s: %w", in.display, err)
		}
	case !in.link:
		return nil, fmt.Errorf("%s isn't a regular file", in.display)
	default:
	}
	in.perm = f.wantPerm(in.curPerm, in.regular)
	return in, nil
}

// wantPerm returns the permissions the file should have, given those of
// the file that's there (cur), if there is one.
func (f *File) wantPerm(cur fs.FileMode, exists bool) fs.FileMode {
	if f.Mode != 0 {
		return f.Mode.Perm()
	}
	perm := fs.FileMode(0o644)
	if exists {
		perm = cur.Perm() &^ 0o111
	}
	if f.Executable {
		// Whoever may read it may run it.
		perm |= (perm & 0o444) >> 2
	}
	return perm
}

// recorded reports whether there's a record of what maisys last wrote.
func (in *inspection) recorded() bool {
	return in.prev.Details[DetailHash] != ""
}

// record returns the record of the file once it holds what it should: the
// hash of that, whether it's written as root, and whether maisys took it
// over, which it did if it was there before maisys recorded writing it.
func (f *File) record(in *inspection) state.Record {
	rec := state.Record{
		Paths:    []string{in.display},
		Details:  map[string]string{DetailHash: hash(in.want)},
		TookOver: in.prev.TookOver || in.exists && !in.recorded(),
	}
	if f.Root {
		rec.Details[DetailRoot] = "true"
	}
	return rec
}

// current reports whether the state file's record says what rec does.
// Details other resources keep in it, such as a unit's name, don't count.
func (in *inspection) current(rec state.Record) bool {
	return in.prev.Details[DetailHash] == rec.Details[DetailHash] &&
		in.prev.Details[DetailRoot] == rec.Details[DetailRoot] &&
		in.prev.TookOver == rec.TookOver && slices.Equal(in.prev.Paths, rec.Paths)
}

// sameContent reports whether the file holds what it should, as a regular
// file or a link to one.
func (in *inspection) sameContent() bool {
	return in.regular && bytes.Equal(in.cur, in.want)
}

// permDiffers reports whether the file's permissions need changing.
// Windows has no permission bits.
func (in *inspection) permDiffers() bool {
	return runtime.GOOS != "windows" && in.regular && in.curPerm != in.perm
}

// unchangedSinceWritten reports whether the file holds what maisys last
// wrote to it.
func (in *inspection) unchangedSinceWritten() bool {
	return in.recorded() && in.regular && hash(in.cur) == in.prev.Details[DetailHash]
}

// needsBackup reports whether applying overwrites contents maisys didn't
// write.
func (in *inspection) needsBackup() bool {
	return in.exists && !in.sameContent() && !in.unchangedSinceWritten()
}

// change returns what applying would do.
func (in *inspection) change() resource.Change {
	switch {
	case !in.exists:
		return resource.Change{Action: resource.Create, Summary: in.display}
	case in.sameContent() && in.permDiffers():
		return resource.Change{Action: resource.Update, Summary: fmt.Sprintf("%s (mode %04o → %04o)", in.display, in.curPerm, in.perm)}
	case in.sameContent():
		return resource.Change{}
	case in.unchangedSinceWritten():
		return resource.Change{Action: resource.Update, Summary: in.display}
	case in.recorded():
		return resource.Change{Action: resource.Warn, Summary: in.display + " changed outside maisys (will back up and overwrite)"}
	default:
		return resource.Change{Action: resource.Warn, Summary: in.display + " exists (will back up and take over)"}
	}
}

// backup backs up what's at the file's path before it's overwritten.
func (f *File) backup(ctx context.Context, rt *resource.Runtime, in *inspection) error {
	now := time.Now
	if rt.Now != nil {
		now = rt.Now
	}
	if !f.Root {
		_, err := Backup(in.path, now())
		return err
	}
	name, err := freeName(in.path, now())
	if err != nil {
		return err
	}
	if err := system.InstallFile(ctx, rt.Runner, in.cur, name, in.curPerm); err != nil {
		return fmt.Errorf("backing up %s: %w", in.display, err)
	}
	return nil
}

// Backup copies the file at path to <path>.maisys-bak.<timestamp>, with
// the time now, adding .1, .2 and so on if that name is taken, and returns
// the copy's path. A link is copied as a link.
func Backup(path string, now time.Time) (string, error) {
	info, err := os.Lstat(path)
	if err != nil {
		return "", fmt.Errorf("backing up %s: %w", path, err)
	}
	link := info.Mode()&fs.ModeSymlink != 0
	var target string
	var data []byte
	if link {
		target, err = os.Readlink(path)
	} else {
		data, err = os.ReadFile(path)
	}
	if err != nil {
		return "", fmt.Errorf("backing up %s: %w", path, err)
	}

	base := backupName(path, now)
	for n := 0; ; n++ {
		name := base
		if n > 0 {
			name = fmt.Sprintf("%s.%d", base, n)
		}
		if link {
			err = os.Symlink(target, name)
		} else {
			err = createFile(name, data, info.Mode().Perm())
		}
		switch {
		case errors.Is(err, fs.ErrExist):
			continue
		case err != nil:
			return "", fmt.Errorf("backing up %s: %w", path, err)
		}
		return name, nil
	}
}

// backupName returns the name of a backup of path made at now.
func backupName(path string, now time.Time) string {
	return path + ".maisys-bak." + now.Format("20060102-150405")
}

// freeName returns a name for a backup of path made at now that nothing
// has yet, as Backup names them.
func freeName(path string, now time.Time) (string, error) {
	base := backupName(path, now)
	for n := 0; ; n++ {
		name := base
		if n > 0 {
			name = fmt.Sprintf("%s.%d", base, n)
		}
		_, err := os.Lstat(name)
		switch {
		case errors.Is(err, fs.ErrNotExist):
			return name, nil
		case err != nil:
			return "", fmt.Errorf("backing up %s: %w", path, err)
		}
	}
}

// createFile writes data to a new file called name, failing with
// fs.ErrExist if there's one already.
func createFile(name string, data []byte, perm fs.FileMode) error {
	f, err := os.OpenFile(name, os.O_WRONLY|os.O_CREATE|os.O_EXCL, perm)
	if err != nil {
		return err
	}
	_, err = f.Write(data)
	if cerr := f.Close(); err == nil {
		err = cerr
	}
	if err != nil {
		_ = os.Remove(name)
	}
	return err
}

// write writes data to path with permissions perm: to a temporary file in
// the same folder, which is then renamed over path, so the file is never
// half written, and a link at path is replaced rather than written
// through. It creates the folders path is in if they're missing, readable
// only by you if they're private, such as ~/.ssh.
func write(home, path string, data []byte, perm fs.FileMode) (err error) {
	if err := makeDirs(home, filepath.Dir(path)); err != nil {
		return err
	}
	tmp, err := os.CreateTemp(filepath.Dir(path), "."+filepath.Base(path)+".maisys-*.tmp")
	if err != nil {
		return fmt.Errorf("writing %s: %w", path, err)
	}
	defer func() {
		if err != nil {
			_ = tmp.Close()
			_ = os.Remove(tmp.Name())
			err = fmt.Errorf("writing %s: %w", path, err)
		}
	}()
	if _, err := tmp.Write(data); err != nil {
		return err
	}
	if runtime.GOOS != "windows" {
		if err := tmp.Chmod(perm); err != nil {
			return err
		}
	}
	if err := tmp.Sync(); err != nil {
		return err
	}
	if err := tmp.Close(); err != nil {
		return err
	}
	return os.Rename(tmp.Name(), path)
}

// makeDirs creates the folder dir and the folders it's in, if they're
// missing: those in the private folders of the home folder home with mode
// 0700, and others with 0755.
func makeDirs(home, dir string) error {
	if home != "" {
		for _, name := range privateDirs {
			private := filepath.Join(home, name)
			if rel, err := filepath.Rel(private, dir); err == nil && filepath.IsLocal(rel) {
				if err := os.MkdirAll(private, 0o700); err != nil {
					return err
				}
			}
		}
	}
	return os.MkdirAll(dir, 0o755)
}

// hash returns the sha256 of data, in hex.
func hash(data []byte) string {
	sum := sha256.Sum256(data)
	return hex.EncodeToString(sum[:])
}
